bool has_engine(const andes_sim::Discovery& d, const std::string& id) {
  for (const andes_sim::EngineDescriptor& e : d.engines)
    if (e.id == id) return true;
  return false;
}

const andes_sim::EngineDescriptor* find_engine(const andes_sim::Discovery& d,
                                               const std::string& id) {
  for (const andes_sim::EngineDescriptor& e : d.engines)
    if (e.id == id) return &e;
  return nullptr;
}

